class Solution {
public:
    bool checkSubarraySum(vector<int>& nums, int k) {
        unordered_map<int, int> seen;
        seen[0] = -1;
        long long sum = 0;
        for (int i = 0; i < (int)nums.size(); i++) {
            sum = (sum + nums[i]) % k;
            if (seen.count(sum)) {
                if (i - seen[sum] >= 2) return true;
            } else {
                seen[sum] = i;
            }
        }
        return false;
    }
};
